"""Demo: Euler characteristic of a Hodge diamond and the three reflections."""
from fractions import Fraction
from typing import Callable

Diamond = Callable[[int, int], Fraction]


def euler_char(n: int, h: Diamond) -> Fraction:
    """chi(n, h) = sum_{p,q=0}^{n} (-1)^{p+q} h(p, q)."""
    return sum(Fraction((-1) ** (p + q)) * h(p, q)
               for p in range(n + 1) for q in range(n + 1))


def mirror(n: int, h: Diamond) -> Diamond:
    return lambda p, q: h(n - p, q)


def transpose(h: Diamond) -> Diamond:
    return lambda p, q: h(q, p)


if __name__ == "__main__":
    # generic diamond
    h: Diamond = lambda p, q: Fraction(2 * p + 3 * q + 1)
    for n in range(6):
        chi = euler_char(n, h)
        chi_m = euler_char(n, mirror(n, h))
        print(f"n={n}: chi={chi}, chi(mirror)={chi_m}, "
              f"ratio={(chi_m / chi) if chi else 'n/a'} (expect (-1)^{n})")
    n = 4
    print("transpose invariance:", euler_char(n, transpose(h)) == euler_char(n, h))

"""Demo: the quintic Calabi-Yau threefold and its mirror (Hodge exchange)."""
from fractions import Fraction
from typing import Callable, Dict, Tuple

Diamond = Callable[[int, int], Fraction]


def diamond(table: Dict[Tuple[int, int], int]) -> Diamond:
    return lambda p, q: Fraction(table.get((p, q), 0))


def euler_char(n: int, h: Diamond) -> Fraction:
    return sum(Fraction((-1) ** (p + q)) * h(p, q)
               for p in range(n + 1) for q in range(n + 1))


def mirror(n: int, h: Diamond) -> Diamond:
    return lambda p, q: h(n - p, q)


if __name__ == "__main__":
    quintic = diamond({
        (0, 0): 1, (3, 3): 1, (0, 3): 1, (3, 0): 1,
        (1, 1): 1, (2, 2): 1, (2, 1): 101, (1, 2): 101,
    })
    Y = mirror(3, quintic)
    print("h11(X) =", int(quintic(1, 1)), " h21(X) =", int(quintic(2, 1)))
    print("chi(X)        =", euler_char(3, quintic))   # -200
    print("chi(mirror X) =", euler_char(3, Y))         # +200
    print("Hodge exchange (mirror X)[1,1] = h21(X):",
          Y(1, 1) == quintic(2, 1))

"""Demo: Weil functional equation for P^n and the point-count congruence."""
from fractions import Fraction


def weil_lhs(n: int, q: int, T: Fraction) -> Fraction:
    prod = Fraction(1)
    for i in range(n + 1):
        prod *= Fraction(q) ** (n - i) * T - 1
    return prod


def weil_rhs(n: int, q: int, T: Fraction) -> Fraction:
    prod = Fraction(1)
    for i in range(n + 1):
        prod *= 1 - Fraction(q) ** i * T
    return Fraction((-1) ** (n + 1)) * prod


def point_count(n: int, q: int) -> int:
    return sum(q ** i for i in range(n + 1))


if __name__ == "__main__":
    for n in range(5):
        eq = weil_lhs(n, 3, Fraction(7, 3)) == weil_rhs(n, 3, Fraction(7, 3))
        print(f"n={n}: Weil functional equation holds: {eq}")
    for n in range(5):
        for q in (2, 3, 5):
            N = point_count(n, q)
            print(f"#P^{n}(F_{q}) = {N}, "
                  f"= n+1 mod (q-1): {N % (q - 1) == (n + 1) % (q - 1)}")

