function EULER_CHAR(n, h):
    total <- 0
    for p in 0..n:
        for q in 0..n:
            total <- total + (-1)^(p+q) * h(p,q)
    return total

function MIRROR_EULER(n, h):
    chi <- EULER_CHAR(n, h)
    return (-1)^n * chi

