function WEIL_PRODUCT(n, q, T, reflected):
    prod <- 1
    for i in 0..n:
        if reflected: prod <- prod * (q^(n-i)*T - 1)
        else:         prod <- prod * (1 - q^i*T)
    return prod
# identity: WEIL_PRODUCT(.,reflected=true) = (-1)^(n+1) * WEIL_PRODUCT(.,reflected=false)

function POINT_COUNT_RESIDUE(n, q):
    N <- sum_{i=0}^{n} q^i
    return N mod (q-1)        # equals (n+1) mod (q-1) = chi(P^n) mod (q-1)
